selected.compute:
pool = read('/input/options')
ordered = sorted(pool, key=lambda row: [row[field] for field in goal['order_by']])
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(ordered, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

selected.effects:
if exists('/output/selection'):
    result = read('/output/selection')
    if valid(result):
        delivery = receipt('report')
        if delivery == 'success':
            pass
        elif delivery == 'unknown':
            pass
        elif delivery == 'failure' or delivery == 'unattempted':
            send('report', 'team', result)
else:
    if result is not None:
        write('/output/selection', result)
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
